-- Arachnophobia Mode (mod-temucraft-player-settings): what a player with the setting on sees instead of
-- each spider-family creature display. Made by tools/make_arachnophobia_sql.py from the server DBCs;
-- run the tool again instead of editing by hand. scale: the object scale sent to that player is
-- multiplied by it so the new model is as big as the old one (display only).
-- spider -> crab 224, giant spider -> sand crab 95, mechanical spider -> hermit crab 32, nerubian -> makrura 108, flying nerubian -> wasp 11, spider mount -> crab mount 2
DROP TABLE IF EXISTS `mod_temucraft_arachnophobia`;
CREATE TABLE `mod_temucraft_arachnophobia` (
  `display_from` INT UNSIGNED NOT NULL,
  `display_to` INT UNSIGNED NOT NULL,
  `scale` FLOAT NOT NULL DEFAULT 1,
  `kind` VARCHAR(16) NOT NULL DEFAULT '',
  `comment` VARCHAR(160) NOT NULL DEFAULT '',
  PRIMARY KEY (`display_from`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;




